tests:
test({ sr: 'tekst sa brojem postaje broj', en: 'text with a number becomes a number' }, () => {
  expect(toNumberOr('42', 0)).toBe(42);
});
test({ sr: 'tekst koji nije broj daje fallback', en: 'text that is not a number gives the fallback' }, () => {
  expect(toNumberOr('abc', -1)).toBe(-1);
});
test({ sr: 'undefined daje fallback', en: 'undefined gives the fallback' }, () => {
  expect(toNumberOr(undefined, 7)).toBe(7);
});

hiddenTests:
test('an empty string becomes 0, not the fallback', () => {
  expect(toNumberOr('', 9)).toBe(0);
});
test('spaces around the number are ignored', () => {
  expect(toNumberOr(' 7 ', 0)).toBe(7);
});
test('null becomes 0', () => {
  expect(toNumberOr(null, 3)).toBe(0);
});
test('negative numbers and a number that is already a number', () => {
  expect(toNumberOr('-4', 0)).toBe(-4);
  expect(toNumberOr(12, 0)).toBe(12);
});
test('Infinity is a number, so the fallback is not used', () => {
  expect(toNumberOr('Infinity', 0)).toBe(Infinity);
});

solutions.code:
function toNumberOr(value, fallback) {
  const number = Number(value);
  return Number.isNaN(number) ? fallback : number;
}
